// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.accessibilityimport timber.log.Timberimport android.accessibilityservice.AccessibilityServiceimport android.accessibilityservice.GestureDescriptionimport android.accessibilityservice.GestureDescription.StrokeDescriptionimport android.app.Notificationimport android.graphics.Bitmapimport android.graphics.Pathimport android.graphics.Rectimport android.os.Buildimport android.view.accessibility.AccessibilityEventimport android.view.accessibility.AccessibilityNodeInfoimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.SharedFlowimport kotlinx.coroutines.flow.asSharedFlowimport java.util.concurrent.atomic.AtomicBoolean/** * NOUS — Accessibility Service (Module 9 v1 — Step 9.1, CRITICAL). * * The REAL Android AccessibilityService implementation. This is NOT a stub — * it extends Android's [AccessibilityService] and uses real framework APIs: *  - `performGlobalAction()` — back, home, recents, lock screen, torch *  - `takeScreenshot()` — API 30+ real screenshot capture (no MediaProjection) *  - `dispatchGesture()` — API 24+ real swipe/tap gestures *  - `getRootInActiveWindow()` — real UI tree for screen reading *  - `findAccessibilityNodeInfosByText()` — real button finding for auto-Send * * ## Lifecycle * * Android's framework manages the lifecycle — NOT Hilt. The service is: *  1. Instantiated by Android when user enables it in Settings → Accessibility *  2. `onServiceConnected()` called — we register the instance in [AccessibilityServiceRegistry] *  3. `onAccessibilityEvent()` called for every UI event (window change, click, etc.) *  4. `onUnbind()` called when user disables — we unregister from [AccessibilityServiceRegistry] * * Other components (AutomationEngine, ScreenUnderstandingEngine, etc.) access the * active service via [AccessibilityServiceRegistry.getInstance()] — a static holder * pattern used by Tasker, Macrodroid, and all accessibility automation apps. * * ## Privacy (per strategy v1 §"Privacy & Security") * *  - **Banking app blacklist** — events from banking/payment apps are ignored *  - **Password fields** — `isPassword=true` nodes are never read *  - **No message content logging** — only button text ("Send") is accessed *  - **Screenshot RAM-only** — screenshots are processed + immediately discarded *  - **Persistent notification** — Android requires this when service is active * * ## Event Handling * * The service listens to ALL window + view events but processes only what NOUS needs: *  - `TYPE_WINDOW_STATE_CHANGED` — app opened/closed (for automation triggers) *  - `TYPE_VIEW_CLICKED` — button clicked (for verification) *  - `TYPE_VIEW_TEXT_CHANGED` — text input (for form filling) *  - Other events are ignored (reduces battery + processing overhead) * * @see <a href="docs/strategy/module-9-agent-strategy-v1.md">§Architecture → Pillar 3: NousAccessibilityService</a> */class NousAccessibilityService : AccessibilityService() {    companion object {        private const val TAG = "NousAccessibility"        /**         * Banking/payment apps that NOUS will NEVER automate (privacy hard line).         *         * **P1 fix**: this constant now delegates to [com.roshan.persona.agent.guard.BankingAppGuard.BLACKLIST]         * — the single source of truth for the blacklist. The `BankingAppGuard`         * class is the injectable, Hilt-bound guard consulted by automation         * providers and outbound executors. We keep this `val` here for         * backwards compatibility with existing tests + the inline check         * in [onAccessibilityEvent].         *         * The set itself is an immutable `Set<String>` (built via `setOf(...)`         * at class-load) — no runtime mutation is possible.         */        val BANKING_APP_BLACKLIST: Set<String> =            com.roshan.persona.agent.guard.BankingAppGuard.BLACKLIST    }    /** True if the service is currently active (between onServiceConnected and onUnbind). */    private val isActive = AtomicBoolean(false)    /** Hot stream of accessibility events (for automation triggers + logging). */    private val _events = MutableSharedFlow<AccessibilityEventWrapper>(extraBufferCapacity = 64)    val events: SharedFlow<AccessibilityEventWrapper> = _events.asSharedFlow()    // ═══════════════════════════════════════════════════════════════════════════    // Lifecycle    // ═══════════════════════════════════════════════════════════════════════════    /**     * Called by Android when the service is first connected.     *     * We register this instance in [AccessibilityServiceRegistry] so other     * components can access it.     */    override fun onServiceConnected() {        super.onServiceConnected()        Timber.tag(TAG).i("NousAccessibilityService connected.")        isActive.set(true)        AccessibilityServiceRegistry.register(this)    }    /**     * Called by Android for every accessibility event.     *     * We filter banking apps + emit non-sensitive events to the [events] flow.     */    override fun onAccessibilityEvent(event: AccessibilityEvent?) {        if (event == null || !isActive.get()) return        val packageName = event.packageName?.toString() ?: return        // Privacy hard line: ignore events from banking/payment apps.        if (packageName in BANKING_APP_BLACKLIST) {            Timber.tag(TAG).v("Ignoring event from blacklisted app: $packageName")            return        }        // Wrap + emit (non-blocking, drops if buffer full).        _events.tryEmit(AccessibilityEventWrapper(            eventType = event.eventType,            packageName = packageName,            className = event.className?.toString(),            text = event.text?.map { it.toString() } ?: emptyList(),            timestampMs = event.eventTime,        ))    }    /**     * Called by Android when the service is interrupted.     */    override fun onInterrupt() {        Timber.tag(TAG).w("NousAccessibilityService interrupted.")    }    /**     * Called by Android when the service is being unbound (user disabled it).     *     * We unregister from [AccessibilityServiceRegistry].     */    override fun onUnbind(intent: android.content.Intent?): Boolean {        Timber.tag(TAG).i("NousAccessibilityService unbinding.")        isActive.set(false)        AccessibilityServiceRegistry.unregister()        return super.onUnbind(intent)    }    // ═══════════════════════════════════════════════════════════════════════════    // Global Actions (Back, Home, Recents, Lock, Torch)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Perform a global accessibility action (real Android API).     *     * @param action one of [AccessibilityService.GLOBAL_ACTION_*] constants.     * @return true if the action was performed successfully.     */    fun executeGlobalAction(action: Int): Boolean {        if (!isActive.get()) {            Timber.tag(TAG).w("Service not active — cannot perform global action $action.")            return false        }        val result = performGlobalAction(action)        Timber.tag(TAG).d("Global action $action → $result.")        return result    }    // ═══════════════════════════════════════════════════════════════════════════    // Screenshot Capture (API 30+)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Take a screenshot of the current screen (real Android API, API 30+).     *     * Uses [AccessibilityService.takeScreenshot] — NO MediaProjection consent     * dialog needed. The screenshot is processed in RAM + immediately discarded.     *     * @param callback called with the screenshot bitmap, or null on failure.     */    fun takeScreenshot(callback: (Bitmap?) -> Unit) {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.R) {            Timber.tag(TAG).w("takeScreenshot requires API 30+ (current: ${Build.VERSION.SDK_INT}).")            callback(null)            return        }        if (!isActive.get()) {            Timber.tag(TAG).w("Service not active — cannot take screenshot.")            callback(null)            return        }        takeScreenshot(            System.nanoTime().toInt(),            java.util.concurrent.Executors.newSingleThreadExecutor(),            object : TakeScreenshotCallback {                override fun onSuccess(screenshot: ScreenshotResult) {                    val bitmap = Bitmap.wrapHardwareBuffer(                        screenshot.hardwareBuffer,                        screenshot.colorSpace,                    )                    Timber.tag(TAG).d("Screenshot captured: ${bitmap?.width}x${bitmap?.height}.")                    callback(bitmap)                }                override fun onFailure(errorCode: Int) {                    Timber.tag(TAG).e("Screenshot failed: errorCode=$errorCode.")                    callback(null)                }            },        )    }    // ═══════════════════════════════════════════════════════════════════════════    // UI Tree Access (Screen Reading)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Get the root node of the active window (real Android API).     *     * Used by ScreenUnderstandingEngine for UI tree access.     *     * @return the root [AccessibilityNodeInfo], or null if unavailable.     */    fun getActiveWindowRoot(): AccessibilityNodeInfo? {        if (!isActive.get()) return null        return rootInActiveWindow    }    /**     * Find UI elements by text (real Android API).     *     * Used by OutboundExecutor to find the "Send" button in WhatsApp/Telegram.     *     * @param text the text to search for (e.g., "Send", "Reply").     * @return list of matching [AccessibilityNodeInfo] nodes.     */    fun findNodesByText(text: String): List<AccessibilityNodeInfo> {        val root = rootInActiveWindow ?: return emptyList()        return root.findAccessibilityNodeInfosByText(text)    }    /**     * Find UI elements by view ID (real Android API, API 18+).     *     * @param viewId the full view ID (e.g., "com.whatsapp:id/send").     * @return list of matching nodes.     */    fun findNodesByViewId(viewId: String): List<AccessibilityNodeInfo> {        val root = rootInActiveWindow ?: return emptyList()        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR2) {            root.findAccessibilityNodeInfosByViewId(viewId)        } else {            emptyList()        }    }    /**     * Click a node by text (real Android API).     *     * Finds the node by text + performs ACTION_CLICK.     * Used by OutboundExecutor for WhatsApp auto-Send.     *     * @param text the text on the button to click (e.g., "Send").     * @return true if the click was performed.     */    fun clickNodeByText(text: String): Boolean {        val nodes = findNodesByText(text)        for (node in nodes) {            try {                if (node.isClickable) {                    val result = node.performAction(AccessibilityNodeInfo.ACTION_CLICK)                    Timber.tag(TAG).d("Clicked node with text \"$text\" → $result.")                    return result                }                // Try parent if the node itself isn't clickable (common pattern).                val parent = node.parent                if (parent?.isClickable == true) {                    val result = parent.performAction(AccessibilityNodeInfo.ACTION_CLICK)                    Timber.tag(TAG).d("Clicked parent of node with text \"$text\" → $result.")                    return result                }            } catch (e: IllegalStateException) {                // Node may have been invalidated between findNodesByText and                // performAction (e.g., activity navigated away). Skip + try next.                Timber.tag(TAG).w("Node invalidated before click: ${e.message}")                continue            }        }        Timber.tag(TAG).w("No clickable node found with text \"$text\".")        return false    }    /**     * Set text on a node by view ID (real Android API).     *     * Used for form filling + text input.     *     * @param viewId the view ID of the input field.     * @param text the text to set.     * @return true if the text was set.     */    fun setTextByViewId(viewId: String, text: String): Boolean {        val nodes = findNodesByViewId(viewId)        for (node in nodes) {            val args = android.os.Bundle()            args.putCharSequence(                AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,                text,            )            val result = node.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT, args)            if (result) {                Timber.tag(TAG).d("Set text on view $viewId → \"$text\".")                return true            }        }        Timber.tag(TAG).w("Could not set text on view $viewId.")        return false    }    // ═══════════════════════════════════════════════════════════════════════════    // Gesture Dispatch (Tap + Swipe — API 24+)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Tap at a specific screen coordinate (real Android API, API 24+).     *     * Uses [AccessibilityService.dispatchGesture] with a single-point stroke.     *     * @param x screen X coordinate (pixels).     * @param y screen Y coordinate (pixels).     * @return true if the gesture was dispatched.     */    fun tapAt(x: Float, y: Float): Boolean {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.N) {            Timber.tag(TAG).w("dispatchGesture requires API 24+.")            return false        }        if (!isActive.get()) return false        val path = Path().apply { moveTo(x, y) }        val stroke = StrokeDescription(path, 0, 50)  // 50ms tap duration        val gesture = GestureDescription.Builder()            .addStroke(stroke)            .build()        val result = dispatchGesture(gesture, null, null)        Timber.tag(TAG).d("Tap at ($x, $y) → $result.")        return result    }    /**     * Swipe from one point to another (real Android API, API 24+).     *     * @param startX starting X coordinate.     * @param startY starting Y coordinate.     * @param endX ending X coordinate.     * @param endY ending Y coordinate.     * @param durationMs swipe duration in milliseconds.     * @return true if the gesture was dispatched.     */    fun swipe(        startX: Float,        startY: Float,        endX: Float,        endY: Float,        durationMs: Long = 300,    ): Boolean {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.N) {            Timber.tag(TAG).w("dispatchGesture requires API 24+.")            return false        }        if (!isActive.get()) return false        val path = Path().apply {            moveTo(startX, startY)            lineTo(endX, endY)        }        val stroke = StrokeDescription(path, 0, durationMs)        val gesture = GestureDescription.Builder()            .addStroke(stroke)            .build()        val result = dispatchGesture(gesture, null, null)        Timber.tag(TAG).d("Swipe ($startX,$startY)→($endX,$endY) ${durationMs}ms → $result.")        return result    }    /**     * Long-press at a specific screen coordinate (real Android API, API 24+).     *     * @param x screen X coordinate.     * @param y screen Y coordinate.     * @param durationMs press duration (default 1000ms = long press).     * @return true if dispatched.     */    fun longPressAt(x: Float, y: Float, durationMs: Long = 1000): Boolean {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.N) return false        if (!isActive.get()) return false        val path = Path().apply { moveTo(x, y) }        val stroke = StrokeDescription(path, 0, durationMs)        val gesture = GestureDescription.Builder()            .addStroke(stroke)            .build()        return dispatchGesture(gesture, null, null)    }    // ═══════════════════════════════════════════════════════════════════════════    // Utility    // ═══════════════════════════════════════════════════════════════════════════    /** True if the service is currently active. */    fun isServiceActive(): Boolean = isActive.get()    /**     * Get the screen dimensions (real Android API).     *     * @return [Rect] with screen width/height, or null if unavailable.     */    fun getScreenBounds(): Rect? {        if (!isActive.get()) return null        val displayMetrics = resources.displayMetrics        return Rect(0, 0, displayMetrics.widthPixels, displayMetrics.heightPixels)    }}// ──────────────────────────────────────────────────────────────────────────/** * Wrapper for [AccessibilityEvent] — extracts only the data NOUS needs * (avoids holding a reference to the raw event which may be recycled). */data class AccessibilityEventWrapper(    val eventType: Int,    val packageName: String,    val className: String?,    val text: List<String>,    val timestampMs: Long,) {    /** True if this is a window state change (app opened/closed). */    val isWindowStateChanged: Boolean        get() = eventType == AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED    /** True if this is a view click event. */    val isViewClicked: Boolean        get() = eventType == AccessibilityEvent.TYPE_VIEW_CLICKED    /** True if this is a text change event. */    val isViewTextChanged: Boolean        get() = eventType == AccessibilityEvent.TYPE_VIEW_TEXT_CHANGED}